// Grid: start (1,1), library (1,4), target (3,4)
// Must pass through library
// Path 1: (1,1) → (1,4) = |1-1| + |4-1| = 3 steps
// Path 2: (1,4) → (3,4) = |3-1| + |4-4| = 2 steps
// Total = 5 steps
const start = [1, 1];
const library = [1, 4];
const target = [3, 4];
const dist1 = Math.abs(library[0] - start[0]) + Math.abs(library[1] - start[1]);
const dist2 = Math.abs(target[0] - library[0]) + Math.abs(target[1] - library[1]);
const total = dist1 + dist2;
return "The minimum number of unit steps is " + total + ".";
```

